// src/lib/cameraDevices.js
async function listVideoInputDevices() {
  if (!navigator.mediaDevices?.enumerateDevices) return [];
  const devices = await navigator.mediaDevices.enumerateDevices();
  return devices.filter((d5) => d5.kind === "videoinput");
}
async function openCameraStream(deviceId) {
  return navigator.mediaDevices.getUserMedia({
    video: {
      deviceId: { exact: deviceId },
      width: { ideal: 640 },
      height: { ideal: 360 }
    },
    audio: false
  });
}
function closeCameraStream(stream) {
  if (!stream) return;
  stream.getTracks().forEach((track) => track.stop());
}

// src/lib/screenShare.js
async function startScreenShare() {
  if (!navigator.mediaDevices?.getDisplayMedia) {
    throw new Error("Tr\xECnh duy\u1EC7t n\xE0y kh\xF4ng h\u1ED7 tr\u1EE3 chia s\u1EBB m\xE0n h\xECnh (getDisplayMedia).");
  }
  try {
    const stream = await navigator.mediaDevices.getDisplayMedia({
      video: { cursor: "always" },
      audio: true
    });
    return stream;
  } catch (err) {
    if (err.name === "NotAllowedError" || err.name === "AbortError") {
      return null;
    }
    throw err;
  }
}
function onScreenShareNativeStop(stream, callback) {
  const track = stream?.getVideoTracks?.()[0];
  if (!track) return () => {
  };
  track.addEventListener("ended", callback);
  return () => track.removeEventListener("ended", callback);
}
function stopScreenShare(stream) {
  if (!stream) return;
  stream.getTracks().forEach((track) => track.stop());
}

